#!/usr/bin/env bash
set -euo pipefail
flutter create --platforms=android,ios,web --project-name asset_flow_mobile .
# Remove the generic starter test generated by flutter create; the app requires Firebase initialization.
rm -f test/widget_test.dart
python3 - <<'PY'
from pathlib import Path
p = Path("android/app/src/main/AndroidManifest.xml")
if p.exists():
    s = p.read_text()
    permissions = [
        '    <uses-permission android:name="android.permission.CAMERA" />\n',
        '    <uses-permission android:name="android.permission.INTERNET" />\n',
    ]
    for permission in permissions:
        permission_name = permission.split('name="')[1].split('"')[0]
        if permission_name not in s:
            s = s.replace("<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\">\n",
                          "<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\">\n" + permission)
    p.write_text(s)
p = Path("ios/Podfile")
if p.exists():
    s = p.read_text()
    import re
    if re.search(r"^\s*#\s*platform :ios", s, flags=re.MULTILINE):
        s = re.sub(r"^\s*#\s*platform :ios.*$", "platform :ios, '15.5'", s, count=1, flags=re.MULTILINE)
    elif re.search(r"^platform :ios", s, flags=re.MULTILINE):
        s = re.sub(r"^platform :ios.*$", "platform :ios, '15.5'", s, count=1, flags=re.MULTILINE)
    else:
        s = "platform :ios, '15.5'\n" + s
    p.write_text(s)
p = Path("ios/Runner.xcodeproj/project.pbxproj")
if p.exists():
    s = p.read_text()
    s = re.sub(r"IPHONEOS_DEPLOYMENT_TARGET = [0-9.]+;", "IPHONEOS_DEPLOYMENT_TARGET = 15.5;", s)
    p.write_text(s)
p = Path("ios/Runner/Info.plist")
if p.exists():
    s = p.read_text()
    if "NSCameraUsageDescription" not in s:
        marker = "</dict>"
        index = s.rfind(marker)
        if index >= 0:
            entry = "  <key>NSCameraUsageDescription</key>\n  <string>نحتاج إلى الكاميرا لمسح باركود الأجهزة والعُهد.</string>\n"
            s = s[:index] + entry + s[index:]
            p.write_text(s)
PY
